 def lk(s):
  ans={q:set() for q in range(5)}
  for q in range(s.bit_count(),5):
   for f in faces[q]:
    if f&s==s:ans[q-s.bit_count()].add(f^s)
  return ans
 for size in range(3):
  for s in faces[size]:
   L=lk(s);dim=3-size
   ranks={0:1}
   for q in range(1,dim+2):
