 start=time.time();cnt=0
 while time.time()-start<limit:
  res=S.check()
  if res!=z3.sat:print('result',res,'n',n,'models',cnt,flush=True);break
  m=S.model();F=tuple(sorted(f for f,x in Fs.items() if z3.is_true(m.eval(x))))
